function makeVariant(opts: {
  slug: string;
  sku: string;
  name: string;
  shortDescription: string;
  description: string;
  longDescription?: string;
  categorySlug: string;
  categoryName: string;
  price: number;
  purity?: string;
  concentration?: string;
  images?: ProductImage[];
  featured?: boolean;
  bestSeller?: boolean;
  specifications?: { label: string; value: string }[];
}): Product {
  const defaultImages = getProductImagesForProduct(opts.name, opts.categorySlug);

  return {
    id: `local-${opts.slug}`,
    slug: opts.slug,
    sku: opts.sku,
    name: opts.name,
    shortDescription: opts.shortDescription,
    description: opts.description,
    longDescription: opts.longDescription,
    categorySlug: opts.categorySlug,
    categoryName: opts.categoryName,
    price: opts.price,
    currency: SITE_CURRENCY,
    purity: opts.purity || ">99%",
    concentration: opts.concentration || "Lyophilized Powder",
    images: opts.images && opts.images.length > 0 ? opts.images : defaultImages,
    badges: opts.bestSeller ? ["best-seller"] : opts.featured ? ["new"] : [],
    stock: "in-stock",
    stockCount: 100,
    rating: 4.9,
    reviewCount: 12,
    reviews: [],
    specifications: opts.specifications || [
      { label: "Purity", value: ">99% (HPLC Verified)" },
      { label: "Storage", value: "-20°C (Lyophilized)" },
    ],
    featured: !!opts.featured,
    bestSeller: !!opts.bestSeller,
    createdAt: new Date().toISOString(),
  };
}

